    "mechanism": "Rifampisin dan leflunomide keduanya dapat memengaruhi fungsi hepatosit, menghasilkan risiko aditif pada peningkatan enzim hepar.",
    "clinicalOutcome": "Peningkatan enzim transaminase serum (SGPT/SGOT) yang umumnya asimtomatik atau ringan.",
    "management": "Lakukan pemeriksaan tes fungsi hati (LFT) sebelum inisiasi dan secara berkala setiap 1-2 bulan selama terapi bersamaan.",
    "evidenceLevel": "Level 1 - Well Established (DDInter 2.0 Rule 617)",
    "ddinterPairId": "DDInter-PAIR-128630",
    "ddinterOriginalText": "The recent, concomitant, or subsequent use (without the recommended leflunomide washout period or procedure) of other agents known to induce hepatotoxicity may potentiate the risk of liver injury associated with leflunomide. Pharmacokinetically, coadministration of leflunomide with rifampin may increase the plasma concentrations of M1, the active metabolite of leflunomide that is responsible for essentially all of its activity in vivo. The mechanism has not been described, but may involve rifampin induction of leflunomide metabolism via hepatic CYP450 isoenzymes. Due to the long half-life of M1, levels may continue to increase with multiple dosing of leflunomide.",
    "ddinterOriginalManagement": "Caution is advised if leflunomide is used in combination with rifampin. The potential for increased risk of leflunomide toxicities including peripheral neuropathy, immunosuppression, bone marrow suppression, and hepatotoxicity should be considered. Liver enzymes and bilirubin should be measured prior to initiation of leflunomide therapy and at least monthly for the first six months of treatment and every 6 to 8 weeks thereafter. Patients with preexisting liver disease or elevated baseline liver enzymes (i.e., ALT greater than two times ULN) should not receive leflunomide. Patients who develop elevated serum ALT greater than three times ULN while receiving leflunomide should discontinue treatment and be given washout procedures with cholestyramine or activated charcoal to accelerate elimination of leflunomide&#x27;s active metabolite from plasma, which otherwise may take up to two years. Follow-up monitoring should be conducted at least weekly until the ALT value is within normal range, and washout procedures repeated as necessary. All patients treated with leflunomide should be advised to seek medical attention if they experience potential signs and symptoms of hepatotoxicity such as fever, rash, itching, anorexia, nausea, vomiting, fatigue, malaise, right upper quadrant pain, dark urine, pale stools, and jaundice.",
